{
  "findings": [
    {
      "check_id": "CKV_AZURE_21",
      "title": "Default action set to 'Allow' in storage account network rules",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "HIGH",
      "explanation": "Setting the default_action to 'Allow' permits unrestricted access to the storage account unless explicitly denied by other rules. This increases the risk of unauthorized access."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\"]\n}",
  "fix_summary": "Changed the default_action from 'Allow' to 'Deny' to restrict access by default and only allow explicitly defined IPs."
}
